insert into public.diagnostico_items
  (id, area, tipo, peso, elo, elo_base, enunciado, opciones, fen, correcta, solucion, alternas, explica, lichess, rating)
values
  ('reg_caballo', 'reglas', 'opcion', 1, 790, 700, '¿Cómo se mueve el caballo?', '["En forma de L: dos casillas en una dirección y una perpendicular.","En diagonal, tan lejos como quiera si el camino está libre.","Una sola casilla por turno, en cualquiera de las ocho direcciones.","En línea recta por su fila o su columna, sin límite de casillas."]'::jsonb, null, 0, null, null, 'El caballo es la única pieza que salta: por eso es tan útil en posiciones cerradas.', null, null),
  ('reg_ahogado', 'reglas', 'opcion_tablero', 1, 680, 950, 'Juegan las negras y no tienen ninguna jugada legal, pero su rey NO está en jaque. ¿Qué pasa?', '["Es tablas por ahogado (rey ahogado).","Es jaque mate y ganan las blancas.","Las negras pierden por no poder mover.","Se repite la jugada anterior."]'::jsonb, '7k/5Q2/6K1/8/8/8/8/8 b - - 0 1', 0, null, null, 'Sin jaque y sin jugada legal, la partida es tablas. Con dama y rey hay que vigilar siempre el ahogado.', null, null),
  ('reg_enroque', 'reglas', 'jugada', 1, 760, 950, 'Enroca corto con las blancas.', null, 'r1bqk2r/pppp1ppp/2n2n2/2b1p3/2B1P3/2N2N2/PPPP1PPP/R1BQK2R w KQkq - 6 5', null, '{"from":"e1","to":"g1"}'::jsonb, null, 'El enroque pone al rey a salvo y conecta las torres: en igualdad de condiciones, cuanto antes mejor.', null, null),
  ('reg_al_paso', 'reglas', 'jugada', 1, 730, 1200, 'Las negras acaban de jugar …d7-d5. Captura al paso.', null, '4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 2', null, '{"from":"e5","to":"d6"}'::jsonb, null, 'La captura al paso solo se puede hacer inmediatamente después del avance doble del peón rival.', null, null),
  ('reg_casillas', 'reglas', 'opcion', 1, 580, 700, '¿Cuántas casillas tiene un tablero de ajedrez?', '["60","64","72","81"]'::jsonb, null, 1, null, null, 'El tablero es una cuadrícula de 8×8 = 64 casillas: 32 claras y 32 oscuras.', null, null),
  ('reg_torre_recorrido', 'reglas', 'opcion', 1, 640, 700, '¿Cómo se mueve la torre?', '["En línea recta por su fila o su columna, sin límite de casillas.","En diagonal, tan lejos como quiera si el camino está libre.","En forma de L, como el caballo, saltando por encima de todo.","Una sola casilla por turno, en cualquiera de las ocho direcciones."]'::jsonb, null, 0, null, null, 'La torre se detiene en la primera pieza que encuentra en su camino: no puede saltar, a diferencia del caballo.', null, null),
  ('reg_promocion', 'reglas', 'opcion', 1, 660, 950, 'Un peón que llega a la última fila puede coronar en…', '["En dama, torre, alfil o caballo: nunca en rey ni en peón.","Solo en dama, que es la pieza más fuerte que hay en el juego.","En dama o en caballo, que son las dos que dan mate.","En cualquier pieza, incluido un segundo rey propio."]'::jsonb, null, 0, null, null, 'Coronar en dama es lo más frecuente, pero elegir torre, alfil o caballo a veces evita un ahogado o da un mate más rápido.', null, null),
  ('mat_valores', 'material', 'opcion', 1, 880, 700, 'Sin contar al rey, ¿cuál es el orden correcto de menor a mayor valor?', '["Peón, caballo y alfil, torre, dama.","Peón, torre, caballo y alfil, dama.","Peón, alfil, dama, torre y caballo.","Caballo, peón, torre, alfil, dama."]'::jsonb, null, 0, null, null, 'La escala de siempre: peón 1, caballo y alfil 3, torre 5, dama 9. Son guías, no leyes: la posición manda.', null, null),
  ('mat_dama_gratis', 'material', 'jugada', 1, 450, 700, 'Las negras dejaron algo sin defender. Cóbralo.', null, '6k1/8/8/3q4/8/3R4/6PP/6K1 w - - 0 1', null, '{"from":"d3","to":"d5"}'::jsonb, null, 'Antes de cada jugada, mira qué piezas rivales están sin defensa: es el error más común y el más barato de castigar.', null, null),
  ('mat_torre_gratis', 'material', 'jugada', 1, 680, 950, 'Gana material con una sola jugada.', null, 'r5k1/5ppp/8/8/4B3/8/5PPP/6K1 w - - 0 1', null, '{"from":"e4","to":"a8"}'::jsonb, null, 'Un alfil en una diagonal larga y abierta vigila el tablero de esquina a esquina.', null, null),
  ('mat_cambio', 'material', 'opcion', 1, 820, 950, 'Puedes cambiar tu alfil por una torre rival. ¿Qué es eso y conviene?', '["Es ganar la calidad, dos puntos de ventaja: suele convenir.","Es un cambio parejo en valor: da exactamente igual hacerlo.","Es perder la calidad, así que conviene evitarlo.","Es un cambio que el reglamento no permite hacer."]'::jsonb, null, 0, null, null, 'Torre (5) por alfil o caballo (3) se llama "ganar la calidad". Conviene salvo que la posición diga lo contrario.', null, null),
  ('mat_dama_valor', 'material', 'opcion', 1, 670, 700, '¿Cuál es el valor aproximado de la dama?', '["5","7","9","13"]'::jsonb, null, 2, null, null, 'La dama vale aproximadamente 9 peones: es la pieza más poderosa del tablero.', null, null),
  ('mat_dos_torres_vs_dama', 'material', 'opcion', 2, 1150, 950, '¿Qué suele valer más: dos torres o una dama?', '["Dos torres, diez puntos contra nueve, según la posición.","La dama, siempre y en cualquier posición que se presente.","Da igual: diez y nueve puntos son casi lo mismo.","Dos torres nunca le ganan a una dama bien colocada."]'::jsonb, null, 0, null, null, 'Como referencia de valores, dos torres superan ligeramente a una dama, pero la coordinación de las piezas pesa tanto como la suma de puntos.', null, null),
  ('mat_pareja_alfiles', 'material', 'opcion', 1, 980, 1200, '¿Por qué se considera valiosa la "pareja de alfiles" en posiciones abiertas?', '["Porque entre los dos cubren casillas de los dos colores.","Porque un alfil vale más que un caballo en cualquier posición.","Porque los alfiles no se pueden cambiar por piezas menores.","Porque son las únicas piezas que atacan al rey de lejos."]'::jsonb, null, 0, null, null, 'Un solo alfil solo controla casillas de un color; con los dos, un jugador puede dominar todo el tablero, sobre todo con pocos peones que bloqueen las diagonales.', null, null),
  ('ap_prioridad', 'apertura', 'opcion', 1, 590, 700, 'En las primeras jugadas, ¿cuál es el orden de prioridades?', '["Ocupar el centro, desarrollar las piezas menores y enrocar.","Sacar la dama temprano para atacar lo antes posible.","Avanzar los peones de las columnas de las torres.","Cambiar todas las piezas que se pueda, para ir simplificando."]'::jsonb, null, 0, null, null, 'Centro, desarrollo y rey seguro: con eso solo, una apertura ya está bien jugada.', null, null),
  ('ap_dama_temprano', 'apertura', 'opcion', 1, 820, 950, '¿Por qué no conviene sacar la dama en las primeras jugadas?', '["Porque el rival gana tiempo atacándola mientras desarrolla.","Porque el reglamento no permite moverla antes de la jugada 10.","Porque en la apertura la dama vale menos que en el final.","Porque una vez que sale ya no puede volver a su casilla."]'::jsonb, null, 0, null, null, 'Cada jaque o ataque a tu dama es una jugada de desarrollo gratis para el rival.', null, null),
  ('ap_pieza_repetida', 'apertura', 'opcion', 1, 850, 950, 'En la apertura, mover varias veces la misma pieza sin necesidad…', '["Pierde tiempo: el rival saca piezas nuevas mientras repites.","Es bueno, porque esa pieza termina muy bien colocada.","Da igual: en la apertura lo que importa es el material.","Solo es un problema si la pieza que se repite es un peón suelto."]'::jsonb, null, 0, null, null, 'La apertura es una carrera por sacar piezas: cada repetición te deja una pieza menos en juego.', null, null),
  ('ap_desarrollo', 'apertura', 'jugada', 1, 890, 1200, 'Tu rey sigue en el centro con la posición abierta. Pon el rey a salvo.', null, 'r1bqkb1r/pppp1ppp/2n2n2/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 4 4', null, '{"from":"e1","to":"g1"}'::jsonb, null, 'Con las piezas menores del flanco de rey ya fuera, enrocar es casi siempre la mejor jugada disponible.', null, null),
  ('ap_espanola', 'apertura', 'opcion', 2, 1150, 700, '1.e4 e5 2.Cf3 Cc6 3.Ab5 corresponde a la apertura…', '["Española","Siciliana","Francesa","Escocesa"]'::jsonb, null, 0, null, null, 'Esa secuencia es la Apertura Española o Ruy López, una de las más antiguas y estudiadas del ajedrez.', null, null),
  ('ap_siciliana', 'apertura', 'opcion', 2, 1230, 950, '1.e4 c5 corresponde a la Defensa…', '["Siciliana","Caro-Kann","Francesa","Pirc"]'::jsonb, null, 0, null, null, '1.e4 c5 es la Defensa Siciliana: la respuesta más popular y combativa contra 1.e4.', null, null),
  ('ap_gambito', 'apertura', 'opcion', 2, 1250, 1200, '¿Cuál es la idea principal detrás de un gambito?', '["Sacrificar material a cambio de desarrollo o de iniciativa.","Ganar una pieza gratis, sin dar absolutamente nada a cambio.","Evitar el desarrollo de piezas hasta llegar al final.","Forzar las tablas lo antes posible a fuerza de jaques."]'::jsonb, null, 0, null, null, 'En un gambito se entrega material (normalmente un peón) a cambio de más desarrollo, control del centro o iniciativa.', null, null),
  ('tac_horquilla', 'tactica', 'jugada', 1, 740, 700, 'Encuentra el tenedor de caballo que ataca al rey y a la dama a la vez.', null, '7k/8/3q4/6N1/8/8/8/K7 w - - 0 1', null, '{"from":"g5","to":"f7"}'::jsonb, null, 'El tenedor de caballo es el recurso táctico que más partidas decide entre principiantes: revisa siempre los saltos con jaque.', null, null),
  ('tac_clavada', 'tactica', 'opcion', 1, 1000, 950, '¿Qué es una clavada?', '["Una pieza no se puede mover sin dejar expuesta a otra mejor.","Una pieza queda encerrada por sus propios peones y no sale.","Dos piezas rivales quedan atacadas a la vez por una sola.","Un peón llega a la última fila y se convierte en dama."]'::jsonb, null, 0, null, null, 'Contra una pieza clavada, la receta es atacarla otra vez: no se puede mover para escapar.', null, null),
  ('tac_descubierto', 'tactica', 'jugada', 1, 890, 1200, 'Mueve el caballo de manera que descubras jaque y de paso ataques la dama negra.', null, '4k3/1q6/8/8/4N3/8/8/4R1K1 w - - 0 1', null, '{"from":"e4","to":"c5"}'::jsonb, '[{"from":"e4","to":"d6"}]'::jsonb, 'En el ataque descubierto la pieza que se aparta puede ir a robar donde quiera: el rival está obligado a atender el jaque. Aquí el caballo tiene dos saltos que sirven: Cc5+ y Cd6+ atacan la dama por igual (los otros seis saltos también dan jaque, pero no amenazan la dama).', null, null),
  ('tac_revisar', 'tactica', 'opcion', 1, 940, 950, 'Tu rival acaba de mover. ¿Qué es lo primero que hay que mirar?', '["Qué amenaza esa jugada: jaques, capturas y ataques dobles.","Cuál es tu plan a largo plazo, aunque él amenace algo.","Cuánto tiempo te queda a ti y cuánto le queda a él.","Si puedes cambiar alguna pieza para simplificar la posición."]'::jsonb, null, 0, null, null, 'Jaques, capturas y amenazas — en ese orden, primero las del rival y luego las tuyas. Es la rutina que evita casi todos los descuidos.', null, null),
  ('tac_horquilla2', 'tactica', 'jugada', 1, 780, 950, 'Da jaque con el caballo de manera que además ataques la torre negra.', null, 'r3k3/8/8/1N6/8/8/8/4K3 w - - 0 1', null, '{"from":"b5","to":"c7"}'::jsonb, null, 'Cc7+ es un tenedor familiar clásica: jaque al rey y ataque simultáneo a la torre de a8. Las negras tienen que atender el jaque moviendo el rey, y las blancas cobran la torre en la jugada siguiente.', null, null),
  ('tac_rayosx', 'tactica', 'opcion', 1, 1030, 1200, '¿Qué es un "rayo X" (o clavada relativa) en ajedrez?', '["Cuando una pieza ataca a través de otra a lo que hay detrás.","Cuando dos alfiles propios se cruzan en el centro.","Cuando un peón defiende a otro peón en la misma diagonal larga.","Cuando la dama y la torre atacan la misma casilla."]'::jsonb, null, 0, null, null, 'El rayo X es una línea de ataque que atraviesa una pieza para llegar a otra detrás, parecido a la clavada pero visto desde el otro lado.', null, null),
  ('tac_desviacion', 'tactica', 'opcion', 2, 1180, 950, '¿Cómo se llama la táctica que obliga a una pieza defensora a abandonar la casilla que protegía?', '["Desviación, o eliminación del defensor.","Clavada sobre la pieza defensora.","Promoción de un peón al llegar a la octava.","Ahogado del rey en la esquina."]'::jsonb, null, 0, null, null, 'La desviación ataca o atrae a la pieza que defiende algo importante para forzarla a moverse, dejando esa casilla o pieza sin protección.', null, null),
  ('mate_pasillo', 'mate', 'jugada', 1, 450, 700, 'Da jaque mate en una jugada.', null, '6k1/5ppp/8/8/8/8/8/R5K1 w - - 0 1', null, '{"from":"a1","to":"a8"}'::jsonb, null, 'El mate del pasillo: el rey se ahoga detrás de sus propios peones. Por eso conviene abrir una ventanita a tiempo.', null, null),
  ('mate_dama', 'mate', 'jugada', 1, 700, 950, 'Da jaque mate en una jugada con la dama.', null, '6k1/8/6K1/8/8/8/8/7Q w - - 0 1', null, '{"from":"h1","to":"a8"}'::jsonb, null, 'Con dama y rey, el mate llega cuando el rey propio le quita al rival las casillas de escape. La dama sola no mata.', null, null),
  ('mate_caballo', 'mate', 'jugada', 1, 880, 1200, 'Da jaque mate en una jugada.', null, '6rk/6pp/8/6N1/8/8/8/6K1 w - - 0 1', null, '{"from":"g5","to":"f7"}'::jsonb, null, 'El rey encerrado por sus propias piezas cae ante un solo caballo: es el patrón del "mate de la coz".', null, null),
  ('mate_ventana', 'mate', 'opcion', 1, 1040, 950, 'Tu rey está enrocado corto y tus peones f, g y h siguen en su casilla. ¿Qué medida de seguridad conviene tomar con tiempo?', '["Hacer una ventanita, por ejemplo h2-h3, contra el pasillo.","Avanzar los tres peones del enroque para atacar de una vez.","Sacar el rey hacia el centro lo antes posible.","Cambiar la dama en cuanto haya oportunidad de hacerlo."]'::jsonb, null, 0, null, null, 'Una casilla de escape cuesta un tiempo y evita el mate del pasillo, que es de los finales más frecuentes en torneos escolares.', null, null),
  ('mate_definicion', 'mate', 'opcion', 1, 650, 700, '¿Qué significa exactamente "jaque mate"?', '["El rey está en jaque y no hay jugada legal que lo libre.","El rey está en jaque pero todavía puede llegar a escapar.","Se acabó el tiempo en el reloj y se pierde la partida.","El rey fue capturado y sacado físicamente del tablero."]'::jsonb, null, 0, null, null, 'El rey nunca llega a ser capturado: la partida termina en el instante en que un jaque no tiene ninguna respuesta legal.', null, null),
  ('mate_sofocado', 'mate', 'opcion', 2, 1240, 1200, '¿Cómo se llama el mate en el que el rey está completamente rodeado por sus propias piezas y un caballo da el jaque final?', '["Mate de la coz (smothered mate).","Mate ahogado en la esquina.","Mate del pasillo o última fila.","Mate de la escalera con dos torres."]'::jsonb, null, 0, null, null, 'En el mate de la coz el rey queda bloqueado por sus propias piezas y un caballo rival —que no se puede capturar ni bloquear— le da el jaque final.', null, null),
  ('mate_escalera', 'mate', 'opcion', 1, 900, 950, '¿Cómo se llama la técnica de dar jaque mate con dos torres (o dama y torre), empujando al rey rival fila a fila hacia el borde del tablero?', '["Mate de la escalera.","Mate de la coz.","Mate del pasillo largo.","Mate de Boden."]'::jsonb, null, 0, null, null, 'Dos piezas de largo alcance se turnan para dar jaque, empujando al rey fila a fila hasta acorralarlo en el borde.', null, null),
  ('fin_cuadrado', 'finales', 'opcion_tablero', 1, 1000, 700, 'Juegan las negras. Según la regla del cuadrado, ¿alcanza el rey negro al peón blanco?', '["No: el peón corona antes.","Sí: lo alcanza justo a tiempo.","Depende de dónde esté el rey blanco.","Solo si el peón avanza de a una casilla."]'::jsonb, '8/8/8/2P5/8/8/8/5k1K b - - 0 1', 0, null, null, 'Dibuja el cuadrado desde el peón hasta la casilla de coronación: si el rey no entra en él jugando, no llega.', null, null),
  ('fin_oposicion', 'finales', 'casilla', 1, 990, 950, 'Haz clic en la casilla a la que debe ir el rey blanco para tomar la oposición.', null, '8/8/4k3/8/8/4K3/8/8 w - - 0 1', null, '"e4"'::jsonb, null, 'Oposición: los reyes enfrentados con una casilla de por medio y el turno del rival. Es la llave de los finales de peones.', null, null),
  ('fin_promocion', 'finales', 'jugada', 1, 700, 950, 'Corona el peón.', null, '8/1P6/8/8/8/5k2/8/7K w - - 0 1', null, '{"from":"b7","to":"b8","promotion":"q"}'::jsonb, null, 'Coronar en dama es lo normal; solo se elige otra pieza para evitar un ahogado o para dar un mate de caballo.', null, null),
  ('fin_torre_peon', 'finales', 'opcion', 3, 1660, 1200, 'En un final de torre y peón contra torre, ¿qué es la posición de Philidor?', '["La defensa: torre en la tercera fila y jaques por detrás.","El ataque: el rey se tapa de los jaques con su torre.","Una posición en la que siempre gana el bando que tiene el peón.","La regla que dice que dos torres le ganan a una sola."]'::jsonb, null, 0, null, null, 'Philidor defiende (tablas) y Lucena gana (el puente). Saber cuál es cuál salva y gana muchos medios puntos.', null, null),
  ('fin_rey_activo', 'finales', 'opcion', 2, 1360, 700, 'En los finales, ¿qué suele ser más importante que en la apertura?', '["La actividad del rey, que ya puede salir al centro.","Enrocar lo antes posible para ponerlo a salvo.","Sacar la dama cuanto antes para dar jaques.","Adelantar cuanto antes los peones de las dos torres."]'::jsonb, null, 0, null, null, 'Con menos piezas en el tablero, el rey deja de estar en peligro constante y se convierte en pieza activa clave, sobre todo en finales de peones.', null, null),
  ('fin_peon_pasado', 'finales', 'opcion', 3, 1600, 700, 'Un "peón pasado" es aquel que…', '["El que no tiene peones rivales delante ni al lado.","El que ya cruzó la mitad del tablero en su avance.","El que avanzó dos casillas en su primer movimiento.","El que quedó clavado por un alfil enemigo."]'::jsonb, null, 0, null, null, 'Un peón pasado no puede ser detenido por ningún peón rival en su camino a coronar, lo que lo hace muy valioso en los finales.', null, null),
  ('fin_alfiles_distinto_color', 'finales', 'opcion', 2, 1180, 1200, '¿Qué hace especialmente difícil de ganar un final de alfiles de distinto color, incluso con material de más?', '["Que el alfil rival bloquea las casillas clave y nadie lo echa.","Que en ese final los alfiles valen menos que un peón suelto.","Que los alfiles no pueden defender peones de otro color.","Que con material de más las tablas son imposibles."]'::jsonb, null, 0, null, null, 'Estos finales son famosos por sus tablas "de manual": el alfil defensor puede bloquear para siempre las casillas de su color, aunque el rival tenga varios peones de más.', null, null),
  ('est_columna', 'estrategia', 'jugada', 1, 630, 950, 'Coloca la torre en la única columna abierta del tablero.', null, '6k1/ppp1pppp/8/8/8/8/PPP1PPPP/R5K1 w - - 0 1', null, '{"from":"a1","to":"d1"}'::jsonb, null, 'Las torres quieren columnas abiertas: es la puerta por donde entran al campo rival.', null, null),
  ('est_centro', 'estrategia', 'opcion', 1, 530, 700, '¿Por qué importa tanto el centro del tablero?', '["Porque desde ahí las piezas llegan a muchas más casillas.","Porque el reglamento da puntos extra por ocuparlo.","Porque el rey debe quedarse siempre en el centro.","Porque en el centro del tablero las piezas no se capturan."]'::jsonb, null, 0, null, null, 'Un caballo en el centro domina 8 casillas; en una esquina, solo 2.', null, null),
  ('est_pasado', 'estrategia', 'opcion', 3, 1540, 1200, '¿Qué es un peón pasado y por qué es fuerte?', '["Uno sin peones rivales delante ni al lado: cuesta frenarlo.","Uno que ya cruzó la mitad del tablero y sigue avanzando solo.","Uno que capturó al paso y quedó en columna abierta.","Uno doblado en la misma columna que otro peón propio."]'::jsonb, null, 0, null, null, 'En los finales, un peón pasado y lejano suele valer más que un peón de más en el mismo flanco.', null, null),
  ('est_caballo_puesto', 'estrategia', 'opcion', 2, 1100, 950, 'Un caballo llega a una casilla avanzada donde ningún peón rival puede echarlo. ¿Qué has conseguido?', '["Un puesto avanzado: pieza fuerte y estable en campo rival.","Un caballo en peligro que conviene retirar enseguida.","Una clavada sobre el rey rival que gana material.","Nada especial: el caballo vale igual en cualquier casilla."]'::jsonb, null, 0, null, null, 'Un caballo bien puesto en la quinta o sexta fila, apoyado por un peón, puede valer más que una torre.', null, null),
  ('est_peon_aislado', 'estrategia', 'opcion', 2, 1310, 950, '¿Qué es un "peón aislado"?', '["Un peón sin peones propios en las columnas vecinas.","Un peón que quedó solo porque capturaron a los demás.","Un peón que ya está a punto de coronar en la octava.","Un peón que avanzó dos casillas en su primer salto."]'::jsonb, null, 0, null, null, 'Al no tener peones vecinos que lo respalden, el peón aislado suele necesitar protección constante de las piezas, aunque también da movilidad a cambio.', null, null),
  ('est_alfil_malo', 'estrategia', 'opcion', 1, 1060, 950, '¿Por qué se dice que un alfil es "malo" en ciertas estructuras de peones?', '["Porque sus propios peones le tapan las diagonales.","Porque el alfil no puede capturar piezas rivales.","Porque en esa estructura vale menos que un peón.","Porque no puede salir de su casilla de origen."]'::jsonb, null, 0, null, null, 'Un "alfil malo" queda encerrado por sus propios peones, colocados en casillas del mismo color que el alfil, lo que reduce mucho su actividad.', null, null),
  ('est_mayoria_flanco', 'estrategia', 'opcion', 2, 1100, 1200, 'En estructuras de peones, ¿qué es una "mayoría de peones" en un flanco?', '["Tener más peones que el rival en ese sector.","Tener todos los peones propios en una sola fila.","Tener menos peones que el rival en ese sector.","Tener dos peones doblados en la misma columna."]'::jsonb, null, 0, null, null, 'Una mayoría de peones en un flanco es una ventaja a largo plazo: bien manejada, puede convertirse en un peón pasado que decida el final.', null, null),
  ('cal_casilla_color', 'calculo', 'opcion', 1, 1090, 700, 'Sin mirar el tablero: ¿de qué color es la casilla f5?', '["Es blanca.","Es negra.","Depende del lado.","No existe f5."]'::jsonb, null, 0, null, null, 'Truco: si la letra y el número son "uno par y otro impar", la casilla es blanca. Saberlo ayuda en los finales de alfiles.', null, null)
